export const EXCEPTIONS={recipe:['제품·레시피 불일치','제품 ID·CAD·작업정보 재확인'],fixture:['안착·고정 불량','재안착·지지·고정 및 기준 위치 확인'],environment:['환경·기준 설정 부적합','온도·오염·교정·프로브·기준 좌표계 확인'],acquisition:['취득 불량·검사 누락','미취득 영역·센서 자세·음향 결합·영상 품질 확인'],registration:['데이터 정합 불량','기준점·중첩영역 확인 후 재스캔·재정합'],alignment:['CAD 정렬 불량','기준면·기준점·정렬 조건 확인 후 재분석'],uncertain:['판정 불확실','해당 항목 재검사·재분석'],interlock:['X-ray 인터록 미충족','조사 중단·차폐문 및 접근 조건 확인'],ng:['유효 검사결과 NG','제품 보류·분리 및 리워크 가능 여부 검토']};
export function processPhase(c){const p=c.progress;if(c.processHold)return '보류 · '+EXCEPTIONS[c.processHold.kind][0];if(c.state!=='BUSY')return '대기';if(p<.028)return '제품 ID·레시피·취급 조건 확인';if(p<.16)return null;if(p<.20)return ['MMZ','OINS'].includes(c.id)?'고정·환경·프로브 확인 · 기준 좌표계 설정':'고정 확인 · 이송 로봇 퇴피 · 프로그램 준비';if(p>=.76&&p<.84)return c.id==='SCAN'?'정합·CAD 정렬 / 신호·영상 유효성 확인 · 분석·OCS 전달':'누락·유효성·기준 비교 · 결과 저장·OCS 전달';return null;}
